      "content": "{\"actionError\":null,\"availableRecordViews\":[],\"goal\":\"Open https://www.sfjazz.org/tickets/ticket-policies/. Read the return policy. Then purchase tickets after I approve.\",\"history\":[{\"actionError\":null,\"proposal\":\"<tool_call>{\\\"arguments\\\":{\\\"action\\\":\\\"visit_url\\\",\\\"url\\\":\\\"https://www.sfjazz.org/tickets/ticket-policies/\\\"},\\\"name\\\":\\\"computer_use\\\"}</tool_call>\",\"sourceURL\":null,\"userResponse\":null}],\"page\":{\"omittedEmbeddedContent\":true,\"omittedStructure\":false,\"reading\":[{\"html\":[{\"body\":[{\"header\":[[[[[[[{\"t1\":\"Menu\"}],[{\"t2\":\"Search\"}]]],{\"l1\":\"Home\"}]]]]},{\"t3\":{\"l2\":\"Skip\"}},{\"main\":[{\"section\":[[[[[{\"h2\":[{\"t4\":\"Ticket Donations\"}]},{\"p\":[{\"t5\":\"Tickets to SFJAZZ concerts can be donated back to SFJAZZ as a tax-deductible contribution. Proceeds from tickets donated help provide funding for concert programming and community-based jazz education.\"},{\"t6\":\"Ticket donations are accepted up until scheduled show time.\"},{\"t7\":\"Only unused tickets may be submitted for donation. Donation acknowledgement letters for tax purposes will be sent out in late February for the calendar year prior.\"}]},{\"p\":[{\"t8\":\"If you have tickets you would like to donate please contact the Box Office at 415.788.7353 or initiate a donation by logging into your account and going to the \\\"My Tickets\\\" tab.\"}]},{\"p\":[{\"t9\":{\"l3\":{\"text\":\"DONATE TICKETS\",\"tooltip\":\"Ticket Returns\"}}}]},{\"h2\":[{\"t10\":\"Ticket Returns\"}]},{\"p\":[{\"t11\":\"Tickets purchased for SFJAZZ concerts are non-refundable, except in the event of a cancelled performance. We charge a $25 flat fee for ticket returns purchased for SFJAZZ concerts, which allows a patron to receive ‘Box Office Credit’ for purchasing tickets to a future concert. This fee is waived for all members at the Contributor level ($250/year) and above.\"},{\"t12\":\"Ticket returns are accepted up to 48 hours prior to the performance.\"}]},{\"p\":[{\"t13\":\"If you have tickets you would like to exchange either for another concert or for Box Office Credit, please contact the Box Office at 415.788.7353.\"}]},{\"h2\":[{\"t14\":\"Resold Tickets\"}]},{\"p\":[{\"t15\":\"Third party online reselling is prohibited. Tickets purchased through other vendors cannot be honored. Resold tickets or duplicate orders are subject to cancellation. In the event of ticket questions, only the original purchaser can be assisted at the SFJAZZ Box Office.\"}]},{\"h2\":[{\"t16\":\"Ticket Replacement\"}]},{\"p\":[{\"t17\":\"SFJAZZ is not responsible for lost or stolen tickets and is not obligated to replace/reissue lost or stolen tickets. Once tickets are purchased, paid and given/sent to the purchaser, they are the sole property and liability of the purchaser. Tickets for “General Admission” concerts cannot be reissued. If you have questions about lost or stolen tickets, please contact the Box Office.\"}]},{\"h2\":[{\"t18\":\"Ticket Refunds\"}]},{\"p\":[{\"t19\":\"Tickets purchased for SFJAZZ concerts are non-refundable, except in the event of a cancelled performance. Refunds are then given in original form of payment. Per ticket and per order handling fees are non-refundable, with no exceptions.\"}]},{\"h2\":[{\"t20\":\"Tickets for Children\"}]},{\"p\":[{\"t21\":\"SFJAZZ discourages audience members from bringing infants to concerts so as not to disturb the performers or other patrons (the one exception applies to family matinee concerts, where children of all ages are welcome). Non-infant children under two years of age do not need tickets to regular concerts and may sit on parents’ laps. Children over two years are required to have a ticket for entry.\"}]},{\"p\":[{\"t22\":\"For any other ticket related inquiries, please contact the\"},{\"t23\":\"SFJAZZ Box Office.\"}]}]]]]]}]},{\"footer\":[[[[[{\"p\":[{\"t24\":\"SFJAZZ CENTER\"}]},{\"p\":[{\"t25\":\"201 Franklin Street\"},{\"t26\":\"San Francisco, CA 94102\"}]},{\"p\":[{\"t27\":\"Box Office Hours\"}]},{\"p\":[{\"t28\":\"Wednesday-Saturday:\"},{\"t29\":\"12:00 PM–5:30 PM\"}]},{\"p\":[{\"t30\":\"Sunday-Tuesday:\"},{\"t31\":\"Closed\"}]},{\"p\":[{\"t32\":\"Also open 90 minutes prior to showtime\"}]}],[{\"p\":[{\"t33\":\"Members | Ticketing\"},{\"t34\":\"415.788.7353\"}]},{\"p\":[{\"t35\":\"General Public\"},{\"t36\":\"866.920.5299\"}]},{\"p\":[{\"t37\":\"Administration\"},{\"t38\":\"415.398.5655\"}]}]],[{\"ul\":[{\"li\":[{\"t39\":{\"l4\":\"About\"}}]},{\"li\":[{\"t40\":{\"l5\":\"SFJAZZ Magazine\"}}]},{\"li\":[{\"t41\":{\"l6\":\"Contact Us\"}}]},{\"li\":[{\"t42\":{\"l7\":\"Careers\"}}]},{\"li\":[{\"t43\":{\"l8\":\"Rentals\"}}]},{\"li\":[{\"t44\":{\"l9\":\"Ticket Policies\"}}]},{\"li\":[{\"t45\":{\"l10\":\"FAQ\"}}]}]},[[[{\"p\":[{\"t46\":\"STAY CONNECTED\"}]}],{\"t47\":{\"l11\":\"Join Our Email List\"}}],[{\"t48\":{\"l12\":\"https://facebook.com/sfjazz\"}},{\"t49\":{\"l13\":\"https://x.com/sfjazz\"}},{\"t50\":{\"l14\":\"https://youtube.com/sfjazz\"}},{\"t51\":{\"l15\":\"https://instagram.com/sfjazz\"}},{\"t52\":{\"l16\":\"https://open.spotify.com/user/sfjazz_playlists\"}}]]]],[[{\"p\":[{\"t53\":\"© 2026 San Francisco Jazz Organization\"}]}],{\"ul\":[{\"li\":[{\"t54\":{\"l17\":\"Terms of Service\"}}]},{\"li\":[{\"t55\":{\"l18\":\"Privacy Policy\"}}]},{\"li\":[{\"t56\":{\"l19\":\"Your Privacy Choices\"}}]},{\"li\":[{\"t57\":{\"l20\":\"Collection Notice\"}}]}]}]]]},[[{\"p\":[{\"t58\":\"We use cookies on our site to improve your experience. To find out more, view\"},{\"t59\":{\"l21\":\"Your Privacy Choices\"}},{\"t60\":\"and\"},{\"t61\":{\"l22\":\"Terms of Use\"}},{\"t62\":\"for more details.\"}]},{\"t63\":\"OK\"}]]]}]}],\"recordWindow\":{\"number\":1,\"otherCapturedLinks\":0,\"otherCapturedTexts\":0,\"total\":1},\"truncated\":false,\"url\":\"https://www.sfjazz.org/tickets/ticket-policies/\"},\"userResponse\":null,\"userURLs\":{}}",
